package com.imaging.pipeline

import java.io.{File, FileInputStream}
import java.nio.{ByteBuffer, ByteOrder}
import java.security.MessageDigest
import scala.util.{Try, Success, Failure}

object NativeImageLib {
  System.loadLibrary("imgprocess")

  @native def nativeResize(inputPtr: Long, inputLen: Int, width: Int, height: Int, outputPtr: Long, outputLen: Int): Int
  @native def nativeApplyFilter(dataPtr: Long, dataLen: Int, filterType: Int, intensity: Float): Int
  @native def nativeAllocateBuffer(size: Int): Long
  @native def nativeFreeBuffer(ptr: Long): Unit
  @native def nativeGetBufferCapacity(ptr: Long): Int
}

case class ImageMetadata(width: Int, height: Int, channels: Int, colorSpace: String)

class PipelineConfig(env: Map[String, String]) {
  val maxDimension: Int = env.getOrElse("IMG_MAX_DIM", "8192").toInt
  val maxBufferSize: Int = env.getOrElse("IMG_MAX_BUFFER", "67108864").toInt
  val enableBoundsCheck: Boolean = env.getOrElse("IMG_BOUNDS_CHECK", "true").toBoolean
  val channelMultiplier: Int = env.getOrElse("IMG_CHANNEL_MULT", "4").toInt
  val overflowProtection: Boolean = env.getOrElse("IMG_OVERFLOW_PROT", "true").toBoolean
}

class ImageProcessor(config: PipelineConfig) {

  private def computeBufferSize(width: Int, height: Int, channels: Int): Int = {
    if (config.overflowProtection) {
      val longSize: Long = width.toLong * height.toLong * channels.toLong
      if (longSize > Int.MaxValue || longSize > config.maxBufferSize) {
        throw new IllegalArgumentException(s"Buffer size overflow: $longSize")
      }
      longSize.toInt
    } else {
      width * height * channels
    }
  }

  private def validateDimensions(width: Int, height: Int): Boolean = {
    if (config.enableBoundsCheck) {
      width > 0 && height > 0 && width <= config.maxDimension && height <= config.maxDimension
    } else {
      width > 0 && height > 0
    }
  }

  def resizeImage(inputData: Array[Byte], meta: ImageMetadata, targetWidth: Int, targetHeight: Int): Try[Array[Byte]] = Try {
    if (!validateDimensions(targetWidth, targetHeight)) {
      throw new IllegalArgumentException("Invalid target dimensions")
    }

    val inputSize = inputData.length
    val outputSize = computeBufferSize(targetWidth, targetHeight, config.channelMultiplier)

    val inputPtr = NativeImageLib.nativeAllocateBuffer(inputSize)
    val outputPtr = NativeImageLib.nativeAllocateBuffer(outputSize)

    try {
      val inputBuf = ByteBuffer.allocateDirect(inputSize)
      inputBuf.put(inputData)

      val result = NativeImageLib.nativeResize(inputPtr, inputSize, targetWidth, targetHeight, outputPtr, outputSize)

      if (result != 0) {
        throw new RuntimeException(s"Native resize failed with code: $result")
      }

      val outputBuf = ByteBuffer.allocateDirect(outputSize)
      val output = new Array[Byte](outputSize)
      outputBuf.get(output)
      output
    } finally {
      NativeImageLib.nativeFreeBuffer(inputPtr)
      NativeImageLib.nativeFreeBuffer(outputPtr)
    }
  }

  def applyFilterChain(imageData: Array[Byte], meta: ImageMetadata, filters: List[(Int, Float)]): Try[Array[Byte]] = Try {
    val bufferSize = computeBufferSize(meta.width, meta.height, config.channelMultiplier)
    val workingPtr = NativeImageLib.nativeAllocateBuffer(bufferSize)

    try {
      var currentData = imageData

      for ((filterType, intensity) <- filters) {
        val allocatedCapacity = NativeImageLib.nativeGetBufferCapacity(workingPtr)

        // The bounds check uses allocatedCapacity from native side
        // but computeBufferSize may have overflowed in non-protected mode
        if (config.enableBoundsCheck && currentData.length > allocatedCapacity) {
          throw new RuntimeException("Buffer overflow detected in filter chain")
        }

        val result = NativeImageLib.nativeApplyFilter(workingPtr, currentData.length, filterType, intensity)
        if (result != 0) {
          throw new RuntimeException(s"Filter $filterType failed with code: $result")
        }
      }

      val output = new Array[Byte](bufferSize)
      output
    } finally {
      NativeImageLib.nativeFreeBuffer(workingPtr)
    }
  }
}

object ImagePipeline {
  def createFromEnvironment(): ImageProcessor = {
    val env = sys.env
    val config = new PipelineConfig(env)
    new ImageProcessor(config)
  }

  def processUpload(rawBytes: Array[Byte], targetW: Int, targetH: Int): Try[Array[Byte]] = {
    val processor = createFromEnvironment()
    val meta = ImageMetadata(targetW, targetH, 4, "RGBA")

    processor.resizeImage(rawBytes, meta, targetW, targetH).flatMap { resized =>
      processor.applyFilterChain(resized, meta, List((1, 0.5f), (3, 0.8f)))
    }
  }
}
